package hu.synostream.android;
import android.content.*;import android.widget.*;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;import java.util.*;import java.io.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
@RunWith(AndroidJUnit4.class) public class Android0514Test {
 final Android050FlowTest f=new Android050FlowTest();String owner;File cache;byte[] bytes;String edits="{\"hidden\":{},\"manual\":{},\"groups\":{}}";
 @Before public void init(){f.instrumentation=InstrumentationRegistry.getInstrumentation();f.context=f.instrumentation.getTargetContext();f.app=(SynoApp)f.context.getApplicationContext();f.device=UiDevice.getInstance(f.instrumentation);UiLocale.save(f.context,"hu");}
 @After public void cleanup()throws Exception{f.instrumentation.runOnMainSync(()->{f.app.connectionDraft.close();f.app.forgetConnection();f.app.client=null;f.app.checkNetwork();f.app.cancelScan();f.app.epoch++;});f.cleanup();UiLocale.save(f.context,"hu");}
 void waitFor(java.util.function.BooleanSupplier value)throws Exception{long end=android.os.SystemClock.elapsedRealtime()+15000;while(!value.getAsBoolean()&&android.os.SystemClock.elapsedRealtime()<end)Thread.sleep(50);assertTrue("Operation did not finish",value.getAsBoolean());}
 void visible(String id)throws Exception{f.instrumentation.waitForIdleSync();f.device.waitForIdle();UiObject2 found=f.device.findObject(By.res(f.pkg+":id/"+id));if(found!=null&&found.getVisibleBounds().height()>0)return;new UiScrollable(new UiSelector().scrollable(true)).scrollIntoView(new UiSelector().resourceId(f.pkg+":id/"+id));assertTrue(f.device.wait(Until.hasObject(By.res(f.pkg+":id/"+id)),5000));}
 void set(String id,String value)throws Exception{visible(id);f.device.findObject(By.res(f.pkg+":id/"+id)).setText(value);}
 void click(String id)throws Exception{visible(id);f.click(id);}
 void setup(FakeNas nas)throws Exception{
  f.instrumentation.runOnMainSync(()->{f.app.client=null;f.app.connectionDraft.close();f.app.recovery.reset();f.app.checkNetwork();});
  f.setup(nas,List.of(new Library.Card("/Movies/Demo.Movie.2020.mkv","Manual fixture",true)));owner=AccountIdentity.owner(nas.address(),"fixture-user");
  f.app.store.forget("nas_profile");f.app.store.put("address",nas.address());f.app.store.put("local","");f.app.store.put("ddns","");f.app.store.put("quick","");f.app.store.put("user","fixture-user");f.app.store.put("libraries_owner",owner);f.app.store.forget("password");f.app.store.put("edits:"+owner,edits);f.app.store.put("torrent_sites:"+owner,"[]");f.app.store.put("torrent_choice:"+owner+":keep","[0]");
  f.instrumentation.runOnMainSync(()->{f.app.identity=owner;f.app.edits=new LocalEdits(edits);});cache=f.app.cacheFile(f.app.selected());bytes=new JSONArray().put(f.app.cards.get(0).json()).toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);try(FileOutputStream out=new FileOutputStream(cache)){out.write(bytes);}
 }
 void editor()throws Exception{f.click("menu_button");f.text(UiText.context(f.context).getString(R.string.msg_settings_ab1136));click("settings_connection_edit");assertTrue(f.device.wait(Until.hasObject(By.res(f.pkg+":id/profile_address")),5000));}
 void save()throws Exception{click("profile_save");assertTrue(f.device.wait(Until.gone(By.res(f.pkg+":id/profile_save")),15000));f.instrumentation.waitForIdleSync();}
 void unchanged(FakeNas a,FakeNas b)throws Exception{assertEquals(owner,f.app.identity);assertTrue(cache.exists());assertArrayEquals(bytes,java.nio.file.Files.readAllBytes(cache.toPath()));assertEquals("Manual fixture",f.app.cards.get(0).title);assertEquals(edits,f.app.store.get("edits:"+owner,""));assertEquals("[0]",f.app.store.get("torrent_choice:"+owner+":keep",""));assertEquals(1,a.listRequestRead.getCount());assertEquals(1,b.listRequestRead.getCount());assertFalse(f.app.scanRunning);}
 @Test public void addressAndDdnsEditsKeepIdentityCardsWarmCacheAndDownloadModel()throws Exception{try(FakeNas a=new FakeNas();FakeNas b=new FakeNas()){
  setup(a);NasClient root=f.app.client;List<Library.Card> cards=f.app.cards;f.app.downloads=new DownloadStation(root,f.app.store,owner);DownloadStation model=f.app.downloads;b.files.put("/Movies/Demo.Movie.2020.mkv",new byte[]{9,8,7});
  editor();set("profile_address",b.address());save();unchanged(a,b);assertSame(root,f.app.client);assertSame(cards,f.app.cards);assertSame(model,f.app.downloads);assertArrayEquals(new byte[]{9,8,7},root.readFile("/Movies/Demo.Movie.2020.mkv",100));assertEquals(1,model.tasks().size());assertEquals(2,b.taskRequests);assertEquals(0,a.taskRequests);
  String id=NasProfile.load(f.app.store).id;click("settings_connection_edit");set("profile_address","");click("profile_more");set("profile_ddns",b.address());assertTrue(f.device.takeScreenshot(new File(f.context.getFilesDir(),"0514-profile-hu.png")));save();unchanged(a,b);assertEquals(id,NasProfile.load(f.app.store).id);assertEquals(b.address(),root.settingsCredentials().ddns);assertEquals("DDNS",root.route);assertTrue(f.device.wait(Until.hasObject(By.res(f.pkg+":id/connection_toolbar").text("Kapcsolat: DDNS – közvetlen")),5000));
 }}
 @Test public void loginCheckDoesNotSaveOrConsumeOtpAndFirstUpgradeKeepsCache()throws Exception{try(FakeNas a=new FakeNas();FakeNas b=new FakeNas()){
  setup(a);f.click("menu_button");f.text("Kijelentkezés");assertTrue(f.device.wait(Until.hasObject(By.res(f.pkg+":id/login_address")),5000));set("login_address",b.address());set("login_user","fixture-user");set("login_password","fixture-password");f.text(f.activity().getString(R.string.connection_more));set("login_otp","123456");click("login_connection_test");
  assertTrue(f.device.wait(Until.hasObject(By.res("android:id/message").textContains("Elérhető, a bejelentkezés sikeres")),15000));assertNull(f.app.client);assertEquals(a.address(),f.app.store.get("address",""));assertEquals("",f.app.store.get("nas_profile",""));assertEquals("",b.lastOtp);assertTrue(b.lastSession.startsWith("SynoStreamCheck_"));f.device.findObject(By.res("android:id/button1")).click();click("login_button");assertTrue(f.device.wait(Until.hasObject(By.res(f.pkg+":id/poster_grid")),15000));assertEquals("123456",b.lastOtp);unchanged(a,b);
 }}
 @Test public void failedSaveLeavesActiveConnectionAndStoredProfileUntouched()throws Exception{try(FakeNas a=new FakeNas();FakeNas b=new FakeNas()){
  setup(a);NasProfile p=NasProfile.load(f.app.store);f.app.store.saveProfile(p,f.app.client.settingsCredentials(),true);String original=f.app.store.get("nas_profile","");NasClient root=f.app.client;b.rejectNewLogins=true;editor();set("profile_address",b.address());click("profile_save");waitFor(()->!f.app.busy&&b.authLogins>0);assertEquals(original,f.app.store.get("nas_profile",""));assertEquals(a.address(),f.app.store.get("address",""));assertEquals("fixture-password",f.app.store.secret("password"));assertSame(root,f.app.client);assertArrayEquals(new byte[]{0,1,2,3},root.readFile("/Movies/Demo.Movie.2020.mkv",100));unchanged(a,b);f.device.pressBack();
 }}
 @Test public void editorDraftAndUnrememberedPasswordSurviveRotation()throws Exception{try(FakeNas a=new FakeNas()){
  setup(a);NasProfile p=NasProfile.load(f.app.store);f.app.store.saveProfile(p,f.app.client.settingsCredentials(),false);editor();click("profile_more");set("profile_ddns","https://nas.example.org:5001");f.device.setOrientationLeft();visible("profile_ddns");assertEquals("https://nas.example.org:5001",f.device.findObject(By.res(f.pkg+":id/profile_ddns")).getText());assertTrue(f.device.takeScreenshot(new File(f.context.getFilesDir(),"0514-profile-landscape.png")));MainActivity activity=f.activity();f.instrumentation.runOnMainSync(()->assertEquals("fixture-password",f.app.connectionDraft.credentials.password));assertEquals("",f.app.store.get("password",""));assertEquals("",NasProfile.load(f.app.store).ddns);f.device.pressBack();waitFor(()->!f.app.connectionDraft.open);assertNull(f.app.connectionDraft.credentials);
 }}
 @Test public void connectionEditorAndCheckAreEnglishWhenEnglishIsSelected()throws Exception{try(FakeNas a=new FakeNas()){
  setup(a);UiLocale.save(f.context,"en");MainActivity original=f.activity();f.instrumentation.runOnMainSync(original::recreate);assertTrue(f.device.wait(Until.hasObject(By.res(f.pkg+":id/connection_toolbar").text("Connection: Local network")),10000));editor();assertTrue(f.device.wait(Until.hasObject(By.text("More connection options")),5000));assertTrue(f.device.takeScreenshot(new File(f.context.getFilesDir(),"0514-profile-en.png")));click("profile_test");assertTrue(f.device.wait(Until.hasObject(By.res("android:id/message").textContains("Local network: Available; sign-in successful")),15000));assertEquals("",f.app.store.get("nas_profile",""));f.device.findObject(By.res("android:id/button1")).click();f.device.pressBack();
 }}
}
